<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';
import CmsConnectionReport from './CmsConnectionReport.vue';
import {api,type CmsDiscovery} from '@/services/api';
const props=defineProps<{activeBase?:string;disabled?:boolean}>();
const emit=defineEmits<{connected:[base:string];busy:[value:boolean]}>();
const busy=ref(false),result=ref<CmsDiscovery|null>(null),error=ref('');
async function discover(){if(busy.value||props.disabled)return;busy.value=true;error.value='';try{result.value=await api.discoverCms();if(result.value.connected&&result.value.connectedBase)emit('connected',result.value.connectedBase);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function choose(base:string,siteId:string){if(busy.value||props.disabled)return;busy.value=true;error.value='';try{const saved=await api.cms(base,siteId);emit('connected',saved.cmsStatus.base);if(result.value){result.value.connectedBase=saved.cmsStatus.base;result.value.connected=saved.cmsStatus.ok;}}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
watch(busy,value=>emit('busy',value),{flush:'sync'});
onMounted(discover);
</script>
<template><view class="discovery"><button class="scan" :disabled="busy||disabled" @click="discover">{{busy?'正在服务器上寻找并检测…':'自动寻找并连接 CMS'}}</button><text class="hint">自动识别同服务器上的苹果 CMS，优先通过本地只读通道检测分类与影片，不依赖采集接口开关。当前连接可用时保留；唯一可用站点自动连接，多个可用站点选择一次。</text><text v-if="result?.multiple" class="hint">找到多个可用站点，请选择需要的内容源。</text><view v-for="site in result?.candidates||[]" :key="site.id" class="site"><view><text>{{site.name}}</text><text v-if="site.recognized" class="hint">已识别苹果 CMS</text><text class="hint">{{site.base||'尚未发现可检测的域名，请手动连接'}}</text><text class="hint">地址来源：{{site.source||'CMS 站点配置 / 站点目录'}}</text><details v-if="site.attempts&&site.attempts.length>1"><summary class="hint">查看其他地址的检测记录</summary><view v-for="attempt in site.attempts" :key="attempt.base"><text class="hint">{{attempt.source}} · {{attempt.base}}</text><text class="hint">{{attempt.report.message}}</text></view></details><CmsConnectionReport v-if="site.report" :report="site.report" title="站点内容连接检测"/></view><button v-if="site.report?.ok&&(activeBase??result?.connectedBase)!==site.base" :disabled="busy||disabled" @click="choose(site.base,site.id)">连接此站</button></view><text v-for="warning in result?.warnings||[]" :key="warning" class="hint">{{warning}}</text><text v-if="error" class="failure">{{error}}</text></view></template>
<style scoped>.discovery{padding:14px 0 22px}.scan{padding:12px;background:#8066d7;color:#fff;border-radius:9px;font-size:13px}.hint{display:block;font-size:12px;line-height:1.8;color:var(--studio-muted,#98a5b5);overflow-wrap:anywhere;margin-top:8px}.success{color:#65aa83}.site{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--studio-border,#35415a);padding:14px 0}.site>view{flex:1;min-width:0}.site button{font-size:12px;padding:8px;background:var(--studio-input,#1b2735);color:inherit}.failure{display:block;color:#d95a5a;margin-top:12px}</style>
